import React from "react";
import styles from "./menu.module.css";
import { Link } from "react-router-dom";
// import { MdLibraryMusic } from "react-icons/md";

export default function Menu({ to }) {
    let kor = "";
    switch (to) {
        case "arcana":
            kor = "아르카나";
            break;
        case "savior":
            kor = "구원자";
            break;
        case "deck":
            kor = "덱 구성";
            break;
        case "journey":
            kor = "여정";
            break;
        case "schedule":
            kor = "스케줄러";
            break;
        case "gacha":
            kor = "가챠";
            break;
        case "item":
            kor = "아이템";
            break;
        case "story":
            kor = "스토리";
            break;
        case "music":
            kor = "BGM";
            break;
    }

    return (
        <Link to={to} className={styles["menu"]}>
            {to !== "music" && <img src={`${process.env.PUBLIC_URL}/images/index/${to}.png`} />}
            {to === "music" && <i className="fi fi-rs-music-alt" />}
            <h3>{kor}</h3>
        </Link>
    );
}
