import { createSlice } from "@reduxjs/toolkit";
import originData from "../../../data/schedules.json";
import journeys from "../../../data/journeys.json";

const titleOrder = {
    "기초 평가전": 0,
    "토벌 평가전": 1,
    "원정 평가전": 2,
    "경쟁 평가전": 3,
    합숙훈련: 4,
    "공허 평가전": 5,
    "최종 평가전": 6,
};

const getContentIds = (block) => {
    return block.contents.map((content) => {
        const journeyList = journeys[content];

        if (journeyList) return journeyList[0].id;
        else null;
    });
};

const normalizeSchedules = (originData) => {
    originData.sort((a, b) => a.turn - b.turn);

    const entities = {};
    const hurdleNames = [];

    originData.forEach((schedule) => {
        schedule.befores.forEach((before) => {
            const contentIds = getContentIds(before);

            before.contentIds = contentIds;
        });
        schedule.currents.forEach((current) => {
            const contentIds = getContentIds(current);

            current.contentIds = contentIds;
        });
        schedule.afters.forEach((after) => {
            const contentIds = getContentIds(after);

            after.contentIds = contentIds;
        });

        if (!entities[schedule.title]) {
            hurdleNames.push(schedule.title);
            entities[schedule.title] = [schedule];
        } else {
            entities[schedule.title].push(schedule);
        }
    });

    return { hurdleNames, entities };
};

const { hurdleNames, entities } = normalizeSchedules(originData);
const scheduleSlice = createSlice({
    name: "schedules",
    initialState: {
        hurdleNames,
        entities,
    },
    reducers: {},
});

export default scheduleSlice.reducer;
