import React, { useEffect, useState } from "react";
import styles from "./gacha.module.css";
import StarContainer from "../../components/star-container/star-container";
import Header from "../../components/header/header";
import { useDispatch, useSelector } from "react-redux";
import Footer from "../../components/footer/footer";
import ScrollUpButton from "../../components/buttons/scroll-up-button/scroll-up-button";
import FILTERS from "../../data/filter_config.json";
import { v4 } from "uuid";
import { GACHA_TYPE, GRADE, SSR_TYPE } from "../../functions/gachaFunctions";
import { reset, setIsPickup, setSaviorPickupType, setSnipeTarget, setSnipeType, tryOne, tryTen } from "../../store/reducers/list/gachaList";
import { selectGachaState, selectSnipeGacha, selectSnipeTargetList, selectCurrentSnipeTarget } from "../../store/selectors/gachaSelectors";
import FilterSelect from "../../components/filter-select/filter-select";
import getImageFileName from "../../functions/getImageFileName";

export default function Gacha() {
    const theme = useSelector((state) => state.theme.value);
    const gacha = useSelector(selectGachaState);
    const snipeGacha = useSelector(selectSnipeGacha);
    const snipeTargetList = useSelector(selectSnipeTargetList);
    const currentSnipeTarget = useSelector(selectCurrentSnipeTarget);

    // const [isPickup, setIsPickup] = useState(false);
    const [gachaMode, setGachaMode] = useState(FILTERS.GACHA_GROUP[0].name);
    const [isPlaying, setIsPlaying] = useState();

    const dispatch = useDispatch();

    useEffect(() => {
        if (typeof isPlaying === "number" && snipeGacha.latestList.findIndex((e) => e.name === currentSnipeTarget) !== -1) {
            clearInterval(isPlaying);
            setIsPlaying(undefined);
            return;
        }
    }, [gacha]);

    // 저격 탭 선택 시 기본값 설정
    useEffect(() => {
        if (gachaMode === GACHA_TYPE.SNIPE && !snipeGacha.target && snipeTargetList.length > 0) {
            dispatch(setSnipeTarget(snipeTargetList[0]));
        }
    }, [gachaMode, snipeGacha.target, snipeTargetList]);

    // 구원자/아르카나 타입 변경 시 target 업데이트
    useEffect(() => {
        if (gachaMode === GACHA_TYPE.SNIPE && snipeTargetList.length > 0) {
            // 현재 target이 새 목록에 없으면 첫 번째 항목으로 설정
            if (!snipeTargetList.includes(snipeGacha.target)) {
                dispatch(setSnipeTarget(snipeTargetList[0]));
            }
        }
    }, [snipeTargetList, snipeGacha.target, gachaMode]);

    const getPercent = (value) => {
        return `${(value * 100).toFixed(2)}%`;
    };

    const startAutoPlay = () => {
        const timer = setInterval(() => {
            dispatch(tryTen({ type: GACHA_TYPE.SNIPE }));
        }, 50); // 10ms -> 50ms로 변경하여 CPU 부하 감소

        setIsPlaying(timer);
    };

    return (
        <div id="container" data-theme={theme}>
            {theme === "dark" && <StarContainer />}
            <Header title={"가챠 시뮬레이터"} />

            <div className={styles["gacha-container"]}>
                {/* TODO : tabs */}
                <div className={styles["tabs"]}>
                    {FILTERS.GACHA_GROUP.map((group) => {
                        return (
                            <button
                                type="button"
                                className={`${styles["tab-button"]} ${group.name === gachaMode ? `${styles["active"]}` : ""}`}
                                onClick={() => setGachaMode(group.name)}
                                key={v4()}
                            >
                                {group.value}
                            </button>
                        );
                    })}
                </div>

                {/* TODO : isPickup selector */}
                <div className={styles["mode-selector-wrapper"]}>
                    <div className={styles["mode-selector"]}>
                        <button
                            type="button"
                            className={`${gacha.isPickup ? "" : `${styles["active"]}`}`}
                            onClick={() => {
                                dispatch(setIsPickup(false));
                                // 통상 선택 시 첫 번째 목록으로 target 업데이트
                                if (snipeTargetList.length > 0) {
                                    dispatch(setSnipeTarget(snipeTargetList[0]));
                                }
                            }}
                        >
                            통상
                        </button>
                        <button
                            type="button"
                            className={`${gacha.isPickup ? `${styles["active"]}` : ""}`}
                            onClick={() => {
                                dispatch(setIsPickup(true));
                                // 픽업 선택 시 첫 번째 목록으로 target 업데이트
                                if (snipeTargetList.length > 0) {
                                    dispatch(setSnipeTarget(snipeTargetList[0]));
                                }
                            }}
                        >
                            픽업
                        </button>
                    </div>
                    {gachaMode === GACHA_TYPE.SAVIOR && gacha.isPickup && gacha.pickupHasCosmic && (
                        <div className={styles["target-type-selector"]}>
                            <button
                                type="button"
                                className={`${gacha.saviorPickupType === SSR_TYPE.NOT_COSMIC ? `${styles["active"]}` : ""}`}
                                onClick={() => dispatch(setSaviorPickupType(SSR_TYPE.NOT_COSMIC))}
                            >
                                일반
                            </button>
                            <button
                                type="button"
                                className={`${gacha.saviorPickupType === SSR_TYPE.COSMIC ? `${styles["active"]}` : ""}`}
                                onClick={() => dispatch(setSaviorPickupType(SSR_TYPE.COSMIC))}
                            >
                                코즈믹
                            </button>
                        </div>
                    )}
                </div>

                {/* TODO : summon buttons */}
                <div className={styles["gacha-buttons"]}>
                    {gachaMode !== GACHA_TYPE.SNIPE && (
                        <button type="button" className={styles["one"]} onClick={() => dispatch(tryOne({ type: gachaMode }))}>
                            1회 소환
                        </button>
                    )}
                    {gachaMode !== GACHA_TYPE.SNIPE && (
                        <button type="button" className={styles["ten"]} onClick={() => dispatch(tryTen({ type: gachaMode }))}>
                            10회 소환
                        </button>
                    )}
                    {gachaMode === GACHA_TYPE.SNIPE && (
                        <div className={styles["snipe-controller"]}>
                            <div className={styles["snipe-settings"]}>
                                <FilterSelect list={["구원자", "아르카나"]} selected={gacha.snipe.type} changeFilter={setSnipeType} />
                                <FilterSelect
                                    list={snipeTargetList}
                                    selected={currentSnipeTarget}
                                    changeFilter={setSnipeTarget}
                                    // forceWidth={snipeGacha.type === "아르카나" ? 200 : 150}
                                    forceWidth={200}
                                />
                            </div>
                            <div className={styles["controller"]}>
                                <button
                                    type="button"
                                    className={styles["start"]}
                                    disabled={isPlaying !== undefined ? true : false}
                                    onClick={() => startAutoPlay()}
                                >
                                    시작
                                </button>
                                <button
                                    type="button"
                                    className={styles["stop"]}
                                    disabled={typeof isPlaying !== "number" ? true : false}
                                    onClick={() => {
                                        clearInterval(isPlaying);
                                        setIsPlaying(undefined);
                                    }}
                                >
                                    정지
                                </button>
                                <button
                                    type="button"
                                    className={styles["reset"]}
                                    disabled={isPlaying !== undefined ? true : false}
                                    onClick={() => dispatch(reset(gachaMode))}
                                >
                                    초기화
                                </button>
                            </div>
                        </div>
                    )}
                </div>

                {/* TODO : result container */}
                {/* TODO : total result container */}
                <div className={styles["result-container"]}>
                    <div className={styles["card-list"]}>
                        {gacha[gachaMode].latestList.map((result) => {
                            if (result.id === GRADE.R) {
                                return (
                                    <div className={`${styles["card"]} ${styles["R"]} ${styles["default"]}`} key={v4()}>
                                        <img src={`${process.env.PUBLIC_URL}/images/cards/아르카나.webp`} />
                                        <span>아르카나</span>
                                    </div>
                                );
                            } else {
                                return (
                                    <div
                                        className={`${styles["card"]} ${
                                            (gachaMode === GACHA_TYPE.SNIPE && result.name === currentSnipeTarget) || result.isPickup
                                                ? `${styles["sniped"]}`
                                                : result.isSSR
                                                  ? `${styles["SSR"]}`
                                                  : `${styles["SR"]}`
                                        }`}
                                        key={v4()}
                                    >
                                        <img
                                            src={
                                                gachaMode === GACHA_TYPE.ARCANA || result.gachaType === "아르카나"
                                                    ? `${process.env.PUBLIC_URL}/images/cards/${getImageFileName(result.name)}.webp`
                                                    : `${process.env.PUBLIC_URL}/images/illust/gacha/${result.name}.webp`
                                            }
                                        />
                                        <span>{result.name}</span>
                                    </div>
                                );
                            }
                        })}
                        {gacha[gachaMode].latestList.length === 0 && <div className={styles["guide-msg"]}>원하는 소환을 선택하세요</div>}
                    </div>
                    <div className={styles["results"]}>
                        <div className={styles["texts"]}>
                            <div className={styles["result"]}>
                                <div className={styles["title"]}>총 소환</div>
                                <div className={styles["value"]}>{gacha[gachaMode].total}</div>
                            </div>
                            <div className={styles["result"]}>
                                <div className={styles["title"]}>SSR 획득</div>
                                <div className={styles["value"]}>{gacha[gachaMode].ssr}</div>
                            </div>
                            <div className={styles["result"]}>
                                <div className={styles["title"]}>SSR 확률</div>
                                <div className={styles["value"]}>
                                    {getPercent(gacha[gachaMode].total === 0 ? 0 : gacha[gachaMode].ssr / gacha[gachaMode].total)}
                                </div>
                            </div>
                            <div className={styles["result"]}>
                                <div className={styles["title"]}>픽업 획득</div>
                                <div className={styles["value"]}>{gacha[gachaMode].pickup}</div>
                            </div>
                            <div className={styles["result"]}>
                                <div className={styles["title"]}>픽업 확률</div>
                                <div className={styles["value"]}>
                                    {getPercent(gacha[gachaMode].total === 0 ? 0 : gacha[gachaMode].pickup / gacha[gachaMode].total)}
                                </div>
                            </div>
                        </div>
                        <div className={styles["badges"]}>
                            {Object.keys(gacha[gachaMode].results).map((charName) => {
                                return (
                                    <span
                                        className={`${styles["badge"]} ${
                                            gacha[gachaMode].results[charName].isSSR ? `${styles["SSR"]}` : `${styles["SR"]}`
                                        }`}
                                        key={v4()}
                                    >
                                        {charName} * {gacha[gachaMode].results[charName].count}
                                    </span>
                                );
                            })}
                        </div>
                        <button type="button" className={styles["reset-button"]} onClick={() => dispatch(reset(gachaMode))}>
                            통계 초기화
                        </button>
                    </div>
                </div>
            </div>

            <ScrollUpButton />
            <Footer />
        </div>
    );
}
