import buffs from "../data/buffs.json";

const colorTagRegex = new RegExp("<color=#(?<color>[0-9A-F]{6})>", "gm");
const bColorTagRegex = new RegExp("<b><color=#(?<color>[0-9A-F]{6})>", "gm");

const replaceColorTag = (string) => {
    let result = bColorTagRegex.exec(string);
    if (!result) return string;

    while (result) {
        string = string.replaceAll(bColorTagRegex, `<b style="color: #${result.groups.color};">`);
        result = bColorTagRegex.exec(string);
    }

    return string.replaceAll("</color>", "");
};

const changeColorTagToSpan = (string) => {
    let result = colorTagRegex.exec(string);
    if (!result) return string;

    while (result) {
        string = string.replaceAll(colorTagRegex, `<span style="color: #${result.groups.color};">`);
        result = colorTagRegex.exec(string);
    }

    return string.replaceAll("</color>", "</span>");
};

const toUnicodeRegexpString = (str) => {
    return str.replaceAll("(", "\\(").replaceAll(")", "\\)").replaceAll("-", "\\-");
};

const getSkillDescWithFlavorTexts = (desc) => {
    const buffList = [];

    buffs.forEach((buff) => {
        if (desc.includes(buff.name) && !buffList.find((e) => e.name === buff.name)) {
            const regex = new RegExp(`<b><color=#(?<color>[0-9a-fA-F]{6})>${toUnicodeRegexpString(buff.name)}`, "g");
            if (regex.test(desc)) {
                buffList.push(buff);
            }
        }
    });

    return {
        desc: replaceColorTag(desc),
        buffList: buffList,
    };
};

const FACTOR_KOR = {
    atk_factor: "공격력 계수",
    hp_factor: "생명력 계수",
    def_factor: "방어력 계수",
    spd_factor: "속도 계수",
};
const getFactorTag = (skill) => {
    const texts = [];
    if (Object.values(skill.factors.damage_factor).reduce((p, c) => p + c) > 0) {
        texts.push("대미지 계수");
        Object.keys(skill.factors.damage_factor).forEach((factor_eng) => {
            if (skill.factors.damage_factor[factor_eng] !== 0) {
                texts.push(`&nbsp;&nbsp;${FACTOR_KOR[factor_eng]} - ${skill.factors.damage_factor[factor_eng] / 10_000}`);
            }
        });
    }
    if (
        Object.values(skill.factors.heal_factor).reduce((p, c) => p + c) > 0 ||
        skill.levels[0].se_list.find((e) => e.healRate !== null) !== undefined
    ) {
        texts.push("회복 계수");
        Object.keys(skill.factors.heal_factor).forEach((factor_eng) => {
            const stat = factor_eng.replace("_factor", "");
            const healSe = skill.levels[0].se_list.find((e) => e.healStatType === stat && e.healRate !== null);

            if (skill.factors.heal_factor[factor_eng] !== 0 || (healSe !== undefined && healSe.healRate !== null)) {
                texts.push(
                    `&nbsp;&nbsp;${FACTOR_KOR[factor_eng]} - ${(skill.factors.heal_factor[factor_eng] + (healSe ? healSe.healRate : 0)) / 10_000}`,
                );
            }
        });
    }
    if (skill.levels[0].se_list.find((e) => e.barrierRate !== null) !== undefined) {
        texts.push("보호막 계수");
        const barrierSe = skill.levels[0].se_list.find((e) => e.barrierRate !== null);
        if (barrierSe) {
            texts.push(`&nbsp;&nbsp;${FACTOR_KOR[`${barrierSe.barrierStatType}_factor`]} - ${barrierSe.barrierRate / 10_000}`);
        }
    }

    return texts.join("<br />");
};

export { replaceColorTag, changeColorTagToSpan, getSkillDescWithFlavorTexts, getFactorTag };
