import React from "react";
import styles from "./modal-right.module.css";
import Stat from "./stat";
import { v4 } from "uuid";
import Event from "./event";
import getImageFileName from "../../../../functions/getImageFileName";

export default function ModalRight({ selected, levelFlag }) {
    return (
        <div className={styles["modal-right"]}>
            <div className={styles["base-info-wrapper"]}>
                <div className={styles["arcana-image"]}>
                    <img src={`${process.env.PUBLIC_URL}/images/cards/${getImageFileName(selected.name)}.webp`} />
                </div>
                <div className={styles["base-info"]}>
                    <div className={styles["modal-header"]}>
                        <h2>{selected.name}</h2>
                        <div className={styles["badges"]}>
                            <span className={`${styles["rarity-badge"]} ${styles[selected.rarity]}`}>{selected.rarity}</span>
                            <p className="char-name">{selected.charName}</p>
                        </div>
                    </div>
                    <div className={styles["group"]}>
                        <h3>타입</h3>
                        <div className={styles["badges"]}>
                            <span className={`${styles["badge"]} ${styles["training"]}`}>{selected.mainStat}</span>
                            {selected.assists.length > 0 && (
                                <span className={`${styles["badge"]} ${styles["support"]}`}>{selected.assists[0]}</span>
                            )}
                            {selected.assists.length > 0 && (
                                <span className={`${styles["badge"]} ${styles["support"]}`}>{selected.assists[1]}</span>
                            )}
                        </div>
                    </div>
                    {(selected.spPotential || selected.uniqueEffect) && (
                        <div className={styles["group"]}>
                            <h3>고유 능력</h3>
                            <div className={styles["group-info"]}>
                                {selected.spPotential && (
                                    <div className={styles["box"]}>
                                        <div className={styles["title"]}>특수 잠재력 : {selected.spPotential.name}</div>
                                        <div className={styles["desc"]}>{selected.spPotential.desc}</div>
                                    </div>
                                )}
                                {selected.uniqueEffect && (
                                    <div className={styles["box"]}>
                                        <div className={styles["title"]}>고유 효과 : {selected.uniqueEffect.name}</div>
                                        <div className={styles["desc"]}>{selected.uniqueEffect.desc}</div>
                                    </div>
                                )}
                            </div>
                        </div>
                    )}
                </div>
            </div>
            {selected.stats.journeyStartStats.length > 0 && (
                <div className={styles["group"]}>
                    <h3>여정 시작 효과</h3>
                    <div className={`${styles["group-info"]} ${styles["row"]}`}>
                        {selected.stats.journeyStartStats.map((stat) => {
                            return (
                                <div className={styles["box"]} key={v4()}>
                                    <Stat obj={stat} levelFlag={levelFlag} isThin={false} mainStat={selected.mainStat} />
                                </div>
                            );
                        })}
                    </div>
                </div>
            )}
            <div className={styles["group"]}>
                <h3>추가 효과</h3>
                <div className={`${styles["group-info"]} ${styles["grid"]}`}>
                    {selected.stats.trainingEffects.length > 0 && (
                        <div className={styles["box"]}>
                            <div className={styles["title"]}>훈련 보너스</div>
                            {selected.stats.trainingEffects.map((stat) => {
                                return <Stat obj={stat} levelFlag={levelFlag} isThin={true} key={v4()} />;
                            })}
                        </div>
                    )}
                    {selected.stats.telepathyEffects.length > 0 && (
                        <div className={styles["box"]}>
                            <div className={styles["title"]}>감응 훈련</div>
                            {selected.stats.telepathyEffects.map((stat) => {
                                return <Stat obj={stat} levelFlag={levelFlag} isThin={true} key={v4()} />;
                            })}
                        </div>
                    )}
                    {selected.stats.supportQuestEffects.length > 0 && (
                        <div className={styles["box"]}>
                            <div className={styles["title"]}>지원 의뢰 효과</div>
                            {selected.stats.supportQuestEffects.map((stat) => {
                                return <Stat obj={stat} levelFlag={levelFlag} isThin={true} key={v4()} />;
                            })}
                        </div>
                    )}
                </div>
            </div>
            <div className={styles["group"]}>
                <h3>이벤트</h3>
                <div className={styles["events"]}>
                    {selected.events.map((event) => {
                        return <Event event={event} key={v4()} />;
                    })}
                </div>
            </div>
        </div>
    );
}
