import React, { useCallback } from "react";
import styles from "./search-box.module.css";

export default function SearchBox({ changeQuery, placeholder }) {
    const handleInput = (e) => {
        debounce(e.target.value);
    };

    const debounceFunction = (callback, delay) => {
        let timer;
        return (value) => {
            clearTimeout(timer);
            timer = setTimeout(() => callback(value), delay);
        };
    };

    const debounce = useCallback(
        debounceFunction((value) => changeQuery(value), 200),
        []
    );

    return (
        <div className={styles["search-box"]}>
            <input type="text" id={styles["savior-search"]} placeholder={placeholder} onInput={handleInput} />
        </div>
    );
}
