import { createSelector } from "@reduxjs/toolkit";
import { choSearch, registQuery } from "../../functions/searchFunctions";
import { selectSelectedDeck } from "./deckSelectors";

export const selectArcanaState = (state) => state.arcanas;

export const selectArcanaEntities = (state) => selectArcanaState(state).entities;

export const selectArcanaIds = (state) => selectArcanaState(state).ids;

export const selectArcanaFavorites = (state) => selectArcanaState(state).favorites;

export const selectArcanaFilter = (state) => selectArcanaState(state).filter;

const filterArcanas = (entity, filter) => {
    if (filter.rarity.value === "all" && filter.status.value === "all") return true;
    if (filter.rarity.value === "all") return filter.status.value === entity.mainStat;
    if (filter.status.value === "all") return filter.rarity.value === entity.rarity;

    return filter.status.value === entity.mainStat && filter.rarity.value === entity.rarity;
};

export const selectArcanasByFilter = createSelector([selectArcanaIds, selectArcanaEntities, selectArcanaFilter], (ids, entities, filter) =>
    ids.filter((id) => filterArcanas(entities[id], filter))
);

export const selectArcanasByQuery = createSelector([selectArcanaEntities, (_, query) => String(query).trim()], (entities, query) => {
    if (query === "") return null;

    registQuery(query);
    return Object.keys(entities)
        .filter((id) => choSearch(entities[id].searchText))
        .map(Number);
});

export const selectArcanasByEventQuery = createSelector([selectArcanaEntities, (_, query) => String(query).trim()], (entities, query) => {
    if (query === "") return null;

    registQuery(query);
    return Object.keys(entities).filter((id) => choSearch(entities[id].eventSearchText));
});

export const selectVisibleArcanas = createSelector(
    [selectArcanasByFilter, selectArcanasByQuery],
    (filteredArcanas, queryFilteredArcanas) => {
        if (!queryFilteredArcanas) return filteredArcanas;

        const querySet = new Set(queryFilteredArcanas);
        return filteredArcanas.filter((id) => querySet.has(id));
    }
);

export const selectIsFavorite = createSelector([selectArcanaFavorites, (_, id) => id], (favorites, id) => favorites.includes(id));

// -------------------------------------------
// deck stats
// -------------------------------------------

const ACC_STAT_TYPE_SCORE = {
    힘: 0,
    체력: 1,
    인내: 2,
    집중: 3,
    보호: 4,
    "인연 포인트 증가": 5,
    "잠재력 포인트 증가": 6,
};

const ADDITIONAL_TYPE_SCORE = {
    "초감응 훈련 효과 상승": 0,
    "훈련 효과 상승": 1,
    "감응 훈련 효과 상승": 2,
    "컨디션 효과 상승": 3,
    "훈련 출현 확률 상승": 4,
    "훈련 실패율 감소": 5,
    "감응 훈련 발생 확률 상승": 6,
};

const STAT_FLAG = {
    ACC: 0,
    ADDITIONAL: 1,
};

const STAT_REF_LIST_NAMES = {
    0: ["journeyStartStats", "supportQuestEffects"],
    1: ["trainingEffects", "telepathyEffects"],
};

const sortAccStats = (stats) => {
    const order = ACC_STAT_TYPE_SCORE;

    return stats.sort((a, b) => {
        const aOrder = Number.isInteger(order[a.type]) ? order[a.type] : 100;
        const bOrder = Number.isInteger(order[b.type]) ? order[b.type] : 100;

        return aOrder - bOrder || (aOrder === 100 && bOrder === 100 ? a.type.localeCompare(b.type, "ko-KR") : 0);
    });
};

const sortAdditionalStats = (stats) => {
    for (let i = 0; i < stats.length; i++) {
        const statObj = stats[i];

        statObj.list.sort((a, b) => {
            const aOrder = Number.isInteger(ADDITIONAL_TYPE_SCORE[a.type]) ? ADDITIONAL_TYPE_SCORE[a.type] : 100;
            const bOrder = Number.isInteger(ADDITIONAL_TYPE_SCORE[b.type]) ? ADDITIONAL_TYPE_SCORE[b.type] : 100;

            return aOrder - bOrder || (aOrder === 100 && bOrder === 100 ? a.type.localeCompare(b.type, "ko-KR") : 0);
        });
    }

    return stats.sort((a, b) => {
        const aOrder = Number.isInteger(ACC_STAT_TYPE_SCORE[a.name]) ? ACC_STAT_TYPE_SCORE[a.name] : 100;
        const bOrder = Number.isInteger(ACC_STAT_TYPE_SCORE[b.name]) ? ACC_STAT_TYPE_SCORE[b.name] : 100;

        return aOrder - bOrder;
    });
};

const getStatValueString = (isRate, value) => {
    return isRate ? `${(value / 100).toFixed(2)}%` : value;
};

const mergeArcanaStats = (arcanas) => {
    const stats = { acc: [], additional: [] };

    arcanas.forEach((arcana) => {
        STAT_REF_LIST_NAMES[STAT_FLAG.ACC].forEach((statName) => {
            arcana.stats[statName].forEach((stat) => {
                let found = stats.acc.find((e) => e.type === stat.type);

                if (!found) {
                    found = {
                        type: stat.type,
                        level_35: stat.level_35,
                        level_50: stat.level_50,
                        isRate: stat.isRate,
                    };

                    stats.acc.push(found);
                } else {
                    found.level_35 += stat.level_35;
                    found.level_50 += stat.level_50;
                }
            });
        });
        STAT_REF_LIST_NAMES[STAT_FLAG.ADDITIONAL].forEach((statName) => {
            arcana.stats[statName].forEach((stat) => {
                let main = stats.additional.find((e) => e.name === arcana.mainStat);
                if (!main) {
                    main = {
                        name: arcana.mainStat,
                        list: [],
                    };

                    stats.additional.push(main);
                }

                let found = main.list.find((e) => e.type === stat.type);

                if (!found) {
                    found = {
                        type: stat.type,
                        level_35: stat.level_35,
                        level_50: stat.level_50,
                        isRate: stat.isRate,
                    };

                    main.list.push(found);
                } else {
                    found.level_35 += stat.level_35;
                    found.level_50 += stat.level_50;
                }
            });
        });
    });

    stats.acc.forEach((stat) => {
        stat.level_35_string = getStatValueString(stat.isRate, stat.level_35);
        stat.level_50_string = getStatValueString(stat.isRate, stat.level_50);
    });
    stats.additional.forEach((mainStat) => {
        mainStat.list.forEach((stat) => {
            stat.level_35_string = getStatValueString(stat.isRate, stat.level_35);
            stat.level_50_string = getStatValueString(stat.isRate, stat.level_50);
        });
    });

    sortAccStats(stats.acc);
    sortAdditionalStats(stats.additional);
    return stats;
};

export const selectSelectedDeckStats = createSelector([selectArcanaEntities, selectSelectedDeck], (arcanaEntities, deck) => {
    if (deck.arcanaIds.length === 0) return null;

    const arcanas = deck.arcanaIds.map((id) => arcanaEntities[id]);
    return mergeArcanaStats(arcanas);
});

export const selectArcanaIdsNotInSelectedDeck = createSelector([selectVisibleArcanas, selectSelectedDeck], (arcanaIds, deck) => {
    return arcanaIds.filter((id) => !deck.arcanaIds.includes(id));
});

export const selectSelectedDeckArcanaIdsIncludesPotential = createSelector(
    [selectArcanaEntities, selectSelectedDeck],
    (arcanaEntities, deck) => {
        return deck.arcanaIds.filter((id) => arcanaEntities[id].spPotential);
    }
);
