import React, { useCallback, useMemo, useState } from "react";
import styles from "./volume-slider.module.css";

export default function VolumeSlider({ volume, setVolume }) {
    const [temp, setTemp] = useState(volume);

    const handleDrag = (e) => {
        const value = e.target.valueAsNumber;
        debounce(value);
        setTemp(value);
    };

    const debounceFunction = (callback, delay) => {
        let timer;
        return (value) => {
            clearTimeout(timer);
            timer = setTimeout(() => callback(value), delay);
        };
    };

    const debounce = useCallback(
        debounceFunction((value) => {
            setVolume(value);
        }, 200),
        [],
    );

    return (
        <div className={styles["volume-slider-container"]}>
            <div className={styles["title"]}>마스터 볼륨 ({Math.floor(temp * 100)}%)</div>
            <div className={styles["volume-slider"]}>
                <input className={styles["thumb"]} type="range" min={0} max={1} step={0.02} value={temp} onChange={handleDrag} />
            </div>
        </div>
    );
}
