import React from "react";
import styles from "./event-description.module.css";
import { v4 } from "uuid";
import StandardRewardRow from "../../journey/standard-reward-row";
import journeyItems from "../../../data/journey_items.json";

const multipleRegions = ["플로라", "칼라이드"];

export default function EventDescription({ selected, desc, showEventName = true, isArcana = false }) {
    const hasChoices = selected.variants[0].choices.length > 1 || selected.variants[0].choices[0].name !== "";

    return (
        <div
            className={`${styles["event-descritpions"]} ${showEventName ? "" : `${styles["upper-line"]}`} ${
                isArcana ? `${styles["arcana"]}` : ""
            }`}
        >
            {showEventName && <div className={styles["event-name"]}>{selected.name ?? selected.variants[0].name}</div>}
            {(selected.times || multipleRegions.includes(desc.region)) && (
                <div className={styles["event-conditions"]}>
                    {selected.times.length > 0 &&
                        selected.times.map((time) => {
                            return (
                                <span className={`${styles["condition"]} ${styles["time"]}`} key={v4()}>
                                    {time}
                                </span>
                            );
                        })}
                    {multipleRegions.includes(desc.region) && (
                        <span className={`${styles["condition"]} ${styles["region"]}`}>{desc.region}</span>
                    )}
                </div>
            )}
            <div className={styles["choices"]}>
                {/* 보상 */}
                {selected.variants[0].choices.map((choice, choiceIndex) => {
                    const choiceName = choice.name;

                    return (
                        <div className={styles["choice"]} key={v4()}>
                            {/* 이름+조건 */}
                            <div className={styles["choice-header"]}>
                                {choice.name !== "" && (
                                    <span className={styles["choice-name"]}>
                                        {hasChoices ? `${choiceIndex + 1}. ${choice.name}` : `${choice.name}`}
                                        {/* {index + 1}. {choice.name} */}
                                    </span>
                                )}
                            </div>
                            {/* 보상 */}
                            <div className={styles["rewards"]}>
                                {choice.success_rewards.length > 0 && (
                                    <div className={`${styles["reward-wrapper"]} ${styles["success"]}`} key={v4()}>
                                        {selected.variants.map((variant, variantIndex) => {
                                            const choice = variant.choices[choiceIndex];

                                            return (
                                                <div className={styles["reward-group"]}>
                                                    {(variant.difficultyKor || choice.condition) && (
                                                        <div className={styles["choice-condition"]}>
                                                            {variant.difficultyKor && (
                                                                <div className={`${styles["badge"]} ${styles[variant.difficultyEng]}`}>
                                                                    {variant.difficultyKor}
                                                                </div>
                                                            )}
                                                            {choice.condition && (
                                                                <div className={`${styles["badge"]} ${styles["item"]}`}>
                                                                    {choice.condition.type === "스탯" &&
                                                                        `${choice.condition.target} ${choice.condition.value} 필요`}
                                                                    {choice.condition.type === "스태미나 소모" &&
                                                                        `스태미나 ${choice.condition.value} 소모`}
                                                                    {choice.condition.type === "아이템 보유" && (
                                                                        <div>
                                                                            <img
                                                                                src={`${process.env.PUBLIC_URL}/images/item/${choice.condition.item.name}.webp`}
                                                                            />
                                                                            {`${choice.condition.item.name} 보유`}
                                                                        </div>
                                                                    )}
                                                                    {choice.condition.type === "아이템 소모" && (
                                                                        <div>
                                                                            <img
                                                                                src={`${process.env.PUBLIC_URL}/images/item/${choice.condition.item.name}.webp`}
                                                                            />
                                                                            {`${choice.condition.item.name} 소모`}
                                                                        </div>
                                                                    )}
                                                                    {choice.condition.type === "오래된 주화 소모" &&
                                                                        `오래된 주화 ${choice.condition.value} 소모`}
                                                                    {choice.condition.type === "잠재력 포인트 소모" &&
                                                                        `잠재력 포인트 ${choice.condition.value} 소모`}
                                                                </div>
                                                            )}
                                                        </div>
                                                    )}
                                                    {choice.success_rewards.map((reward) => {
                                                        return (
                                                            <StandardRewardRow
                                                                reward={reward}
                                                                difficulty={choice.difficultyKor}
                                                                reward_flag={"success"}
                                                                key={v4()}
                                                            />
                                                        );
                                                    })}
                                                    {variantIndex < selected.variants.length - 1 && (
                                                        <div className={styles["group-divider"]}>
                                                            {/* <hr /> */}
                                                            <span className={styles["success"]}>or</span>
                                                        </div>
                                                    )}
                                                </div>
                                            );
                                        })}
                                    </div>
                                )}
                                {choice.success_rewards.length === 0 && <div className={styles["reward-wrapper"]}>없음</div>}
                                {choice.failure_rewards.length > 0 && (
                                    <div className={`${styles["reward-wrapper"]} ${styles["fail"]}`} key={v4()}>
                                        {selected.variants.map((variant, variantIndex) => {
                                            const choice = variant.choices[choiceIndex];

                                            return (
                                                <div className={styles["reward-group"]}>
                                                    {(variant.difficultyKor || choice.condition) && (
                                                        <div className={styles["choice-condition"]}>
                                                            {variant.difficultyKor && (
                                                                <div className={`${styles["badge"]} ${styles[variant.difficultyEng]}`}>
                                                                    {variant.difficultyKor}
                                                                </div>
                                                            )}
                                                            {choice.condition && (
                                                                <div className={`${styles["badge"]} ${styles["item"]}`}>
                                                                    {choice.condition.type === "스탯" &&
                                                                        `${choice.condition.target} ${choice.condition.value} 필요`}
                                                                    {choice.condition.type === "스태미나 소모" &&
                                                                        `스태미나 ${choice.condition.value} 소모`}
                                                                    {choice.condition.type === "아이템 보유" && (
                                                                        <div>
                                                                            <img
                                                                                src={`${process.env.PUBLIC_URL}/images/item/${choice.condition.targetObj.name}.webp`}
                                                                            />
                                                                            {`${choice.condition.targetObj.name} 보유`}
                                                                        </div>
                                                                    )}
                                                                    {choice.condition.type === "아이템 소모" && (
                                                                        <div>
                                                                            <img
                                                                                src={`${process.env.PUBLIC_URL}/images/item/${choice.condition.targetObj.name}.webp`}
                                                                            />
                                                                            {`${choice.condition.targetObj.name} 소모`}
                                                                        </div>
                                                                    )}
                                                                    {choice.condition.type === "오래된 주화 소모" &&
                                                                        `오래된 주화 ${choice.condition.value} 소모`}
                                                                    {choice.condition.type === "잠재력 포인트 소모" &&
                                                                        `잠재력 포인트 ${choice.condition.value} 소모`}
                                                                </div>
                                                            )}
                                                        </div>
                                                    )}
                                                    {choice.failure_rewards.map((reward) => {
                                                        return (
                                                            <StandardRewardRow
                                                                reward={reward}
                                                                difficulty={choice.difficultyKor}
                                                                reward_flag={"fail"}
                                                                key={v4()}
                                                            />
                                                        );
                                                    })}
                                                    {variantIndex < selected.variants.length - 1 && (
                                                        <div className={styles["group-divider"]}>
                                                            {/* <hr /> */}
                                                            <span className={styles["success"]}>or</span>
                                                        </div>
                                                    )}
                                                </div>
                                            );
                                        })}
                                    </div>
                                )}
                                {/* {choice.success_rewards.length === 0 && <div className={styles["reward-wrapper"]}>없음</div>} */}
                            </div>
                        </div>
                    );
                })}
            </div>
        </div>
    );
}
