import React from "react";
import styles from "./item-desc-modal.module.css";
import buffs from "../../data/journey_buffs.json";

export default function ItemDescModal({ selected, isActive, setIsActive }) {
    const getRarityClassName = (rarity) => {
        if (rarity === "전설") return "legendary";
        else if (rarity === "유니크") return "unique";
        else if (rarity === "레어") return "rare";
    };

    const getTypeClassName = (type) => {
        if (type === "음식") return "food";
        else if (type === "훈련 서적") return "book";
        else if (type === "부적") return "charm";
    };

    const getColoredSeText = (text) => {
        const regex = /<b><color=#(?<rgb>[0-9a-fA-F]{6})>/gm;
        const result = regex.exec(text);

        if (result) return text.replaceAll(regex, `<b style="color: #${result.groups.rgb};">`).replaceAll("</color>", "");
        return text;
    };

    return (
        <div
            className={`modal items ${isActive ? "active" : ""}`}
            onClick={(e) => {
                if (e.target.classList.contains("modal")) setIsActive(false);
            }}
        >
            <div className="window">
                <button className="close-button" onClick={() => setIsActive(false)}>
                    <i className="fi fi-sr-x" />
                </button>

                <div className={styles["item-wrapper"]}>
                    <div className={`${styles["item-image"]} ${styles[getRarityClassName(selected.rarity)]}`}>
                        <img src={`${process.env.PUBLIC_URL}/images/item/${selected.name}.webp`} />
                    </div>
                    <div className={styles["item-info"]}>
                        <div className={styles["item-header"]}>
                            <div className={`${styles["item-image"]} ${styles["small"]} ${styles[getRarityClassName(selected.rarity)]}`}>
                                <img src={`${process.env.PUBLIC_URL}/images/item/${selected.name}.webp`} />
                            </div>
                            <div className={styles["item-summary"]}>
                                <div className={styles["item-name"]}>{selected.name}</div>
                                <div className={styles["badges"]}>
                                    <div className={`${styles["badge"]} ${styles[getTypeClassName(selected.type)]}`}>{selected.type}</div>
                                    {selected.charm_info && (
                                        <div className={`${styles["badge"]} ${styles["pp"]}`}>잠재력 {selected.charm_info.pp}</div>
                                    )}
                                    {selected.req_coin && (
                                        <div className={`${styles["badge"]} ${styles["price"]}`}>가격 {selected.req_coin}</div>
                                    )}
                                    {selected.charm_info && (
                                        <div className={`${styles["badge"]} ${styles["target"]}`}>{selected.charm_info.target}</div>
                                    )}
                                </div>
                            </div>
                        </div>
                        <div className={styles["description-wrapper"]}>
                            <div className={styles["title"]}>설명</div>
                            <div className={styles["description"]}>{selected.description}</div>
                        </div>
                        <div className={styles["description-wrapper"]}>
                            <div className={styles["title"]}>효과</div>
                            {selected.type === "부적" && (
                                <div
                                    className={styles["description"]}
                                    dangerouslySetInnerHTML={{ __html: getColoredSeText(selected.charm_info.se_list[0]) }}
                                ></div>
                            )}
                            {selected.type === "훈련 서적" && (
                                <div className={styles["description"]}>
                                    {selected.stats[0].type} +{selected.stats[0].value}
                                </div>
                            )}
                            {selected.type === "음식" &&
                                selected.stats.map((stat) => {
                                    if (stat.type === "여정 버프 습득") {
                                        const buff = buffs.find((e) => e.id === stat.value);

                                        return (
                                            <div className={`${styles["description"]} ${styles["buff"]}`}>
                                                <div className={styles["row"]}>
                                                    {stat.type}{" "}
                                                    <img src={`${process.env.PUBLIC_URL}/images/icon/journey_buff/${buff.icon}`} />
                                                    {buff.name}
                                                </div>
                                                <div className={styles["row"]}>
                                                    <img src={`${process.env.PUBLIC_URL}/images/icon/journey_buff/${buff.icon}`} />{" "}
                                                    {buff.name} : {buff.desc}
                                                </div>
                                            </div>
                                        );
                                    } else if (stat.type === "여정 디버프 해제") {
                                        return <div className={styles["description"]}>{stat.type}</div>;
                                    } else if (typeof stat.min_value === "number") {
                                        return (
                                            <div className={styles["description"]}>
                                                {stat.type} +{stat.min_value} ~ {stat.max_value}
                                            </div>
                                        );
                                    }

                                    return (
                                        <div className={styles["description"]}>
                                            {stat.type} +{stat.value}
                                        </div>
                                    );
                                })}
                            {selected.type === "귀중품" && (
                                <div className={styles["description"]}>
                                    {selected.name === "활력 포션" ? "훈련 실패 이벤트에서 사용" : "-"}
                                </div>
                            )}
                        </div>
                        <div className={styles["description-wrapper"]}>
                            <div className={styles["title"]}>획득처</div>
                            {selected.events &&
                                selected.events.map((event) => {
                                    return <div className={styles["description"]}>{event}</div>;
                                })}
                            {selected.regions && <div className={styles["description"]}>상점({selected.regions.join(", ")})</div>}
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}
