import React, { useEffect, useMemo, useRef, useState } from "react";
import styles from "./audio.module.css";

export default function Audio({ audio, playing, setPlaying, volume }) {
    const [src, setSrc] = useState();
    const audioRef = useRef();

    useEffect(() => {
        import(`../../assets/bgm/${audio.filename}`).then((url) => {
            audioRef.current.volume = 0.7;
            setSrc(url.default);
        });
    }, []);

    useEffect(() => {
        if (audio.music_name !== playing?.music_name) {
            audioRef.current.pause();
        }
    }, [playing]);

    useEffect(() => {
        audioRef.current.volume = volume;
    }, [volume]);

    const places = audio.places?.join(" | ") ?? "";

    const audioComponenet = useMemo(() => {
        return (
            <audio
                ref={audioRef}
                src={src}
                preload="none"
                controls
                controlsList="nodownload nofullscreen noremoteplayback"
                onPlay={() => {
                    setPlaying(audio);
                }}
            />
        );
    }, [src]);

    return (
        <div className={styles["audio-wrapper"]}>
            <div className={styles["summary"]}>
                <div className={styles["music-name"]}>곡명 : {audio.music_name}</div>
                <div className={styles["music-name"]} title={places}>
                    {audio.places ? `플레이 장소 : ${places}` : ""}
                </div>
            </div>
            {audioComponenet}
        </div>
    );
}
