import React, { useState } from "react";
import styles from "./weather-description.module.css";
import { getWeatherEvents } from "../../../functions/getJourneyFunctions";
import FilterSelect from "../../filter-select/filter-select";
import EventDescription from "./event-description";
import { useSelector } from "react-redux";
import { selectJourneyEntities, selectWeatherJourneys } from "../../../store/selectors/journeySelectors";

// const weatherList = getWeatherEvents();

export default function WeatherDescription({ desc }) {
    const journeyEntities = useSelector((state) => selectJourneyEntities(state));
    const weatherJourneys = useSelector((state) => selectWeatherJourneys(state));

    const optionList = [
        { name: "날씨 이벤트", value: "all" },
        ...weatherJourneys.map((id) => {
            const journey = journeyEntities[id];
            return { name: journey.name, value: journey.id };
        }),
    ];

    const [selected, setSeleted] = useState(optionList[0]);

    const tag =
        selected.value !== "all" ? <EventDescription selected={journeyEntities[selected.name]} desc={desc} showEventName={false} /> : <></>;

    return (
        <div className={styles["weather-description"]}>
            <FilterSelect
                id={"weather"}
                list={optionList}
                selected={selected}
                isUseDispatch={false}
                changeFilter={setSeleted}
                forceWidth={280}
            />
            {tag}
        </div>
    );
}
